import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { THREADS_CHANGED_CHANNEL } from '../shared/threads'
import { createThreadInvalidations, THREAD_INVALIDATING_CHANNELS, type ThreadInvalidationWindow } from './thread-invalidations'

const fakeWindow = (state: { destroyed?: boolean; contentsDestroyed?: boolean; throws?: boolean } = {}): ThreadInvalidationWindow & { send: ReturnType<typeof vi.fn> } => {
  const send = vi.fn((_channel: string) => { if (state.throws) throw new Error('window gone') })
  return {
    send,
    isDestroyed: () => Boolean(state.destroyed),
    webContents: { isDestroyed: () => Boolean(state.contentsDestroyed), send }
  }
}

describe('rank9 thread invalidations (main)', () => {
  beforeEach(() => { vi.useFakeTimers() })
  afterEach(() => { vi.useRealTimers(); vi.restoreAllMocks() })

  it('turns a burst of structured events into one payload-free notice per live window', () => {
    const first = fakeWindow(), second = fakeWindow()
    const invalidations = createThreadInvalidations({ windows: () => [first, second], intervalMs: 200 })
    for (let index = 0; index < 500; index += 1) invalidations.observe('structured:events', [{ sessionId: 's', sequence: index, data: { type: 'text', text: 'a secret token' } }])
    expect(first.send).not.toHaveBeenCalled()
    vi.advanceTimersByTime(199)
    expect(first.send).not.toHaveBeenCalled()
    vi.advanceTimersByTime(1)
    for (const window of [first, second]) {
      expect(window.send).toHaveBeenCalledTimes(1)
      // Only the channel: no event data, and so nothing to validate or leak.
      expect(window.send.mock.calls[0]).toEqual([THREADS_CHANGED_CHANNEL])
    }
    vi.advanceTimersByTime(10_000)
    expect(first.send).toHaveBeenCalledTimes(1)
    expect(vi.getTimerCount()).toBe(0)
  })

  it('sends at most one notice per interval while events keep coming, and a trailing one after the last', () => {
    const window = fakeWindow()
    const invalidations = createThreadInvalidations({ windows: () => [window], intervalMs: 200 })
    for (let tick = 0; tick < 10; tick += 1) { invalidations.observe('agent:status', { id: 'a', status: 'running' }); vi.advanceTimersByTime(50) }
    // 500 ms of events: notices at 200 and 400, then the one held at 400..500 leaves at 600.
    expect(window.send).toHaveBeenCalledTimes(2)
    vi.advanceTimersByTime(200)
    expect(window.send).toHaveBeenCalledTimes(3)
    vi.advanceTimersByTime(5_000)
    expect(window.send).toHaveBeenCalledTimes(3)
  })

  it('covers the structural channels main broadcasts and ignores the rest', () => {
    const window = fakeWindow()
    const invalidations = createThreadInvalidations({ windows: () => [window], intervalMs: 10 })
    for (const channel of ['structured:events', 'agent:status', 'projects:changed', 'remote:changed', 'session-archive:changed', 'sessions:restored']) {
      expect(THREAD_INVALIDATING_CHANNELS.has(channel)).toBe(true)
      expect(invalidations.observe(channel, [{}])).toBe(true)
      vi.advanceTimersByTime(10)
    }
    expect(window.send).toHaveBeenCalledTimes(6)
    window.send.mockClear()
    // phone:changed is the desktop's phone-access settings and status, not a conversation event.
    for (const channel of ['phone:changed', 'agent:data', 'agent:event', 'files:changed', 'usage:limits-changed', 'browser:state']) {
      expect(invalidations.observe(channel, {})).toBe(false)
    }
    expect(invalidations.observe('structured:events', [])).toBe(false)
    expect(vi.getTimerCount()).toBe(0)
    vi.advanceTimersByTime(1000)
    expect(window.send).not.toHaveBeenCalled()
  })

  it('skips destroyed windows and survives one that throws', () => {
    const gone = fakeWindow({ destroyed: true }), orphan = fakeWindow({ contentsDestroyed: true }), broken = fakeWindow({ throws: true }), live = fakeWindow()
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => undefined)
    const invalidations = createThreadInvalidations({ windows: () => [gone, orphan, broken, live], intervalMs: 5 })
    expect(() => { invalidations.observe('projects:changed'); vi.advanceTimersByTime(5) }).not.toThrow()
    expect(gone.send).not.toHaveBeenCalled()
    expect(orphan.send).not.toHaveBeenCalled()
    expect(live.send).toHaveBeenCalledTimes(1)
    expect(warn).toHaveBeenCalled()
  })

  it('does not throw when the window list itself fails, and recovers on the next burst', () => {
    const live = fakeWindow()
    let broken = true
    vi.spyOn(console, 'warn').mockImplementation(() => undefined)
    const invalidations = createThreadInvalidations({ windows: () => { if (broken) throw new Error('app closing'); return [live] }, intervalMs: 5 })
    expect(() => { invalidations.notify(); vi.advanceTimersByTime(5) }).not.toThrow()
    broken = false
    invalidations.notify(); vi.advanceTimersByTime(5)
    expect(live.send).toHaveBeenCalledTimes(1)
  })

  it('notify() invalidates for structural handlers that broadcast nothing, and flush() sends a held notice now', () => {
    const window = fakeWindow()
    const invalidations = createThreadInvalidations({ windows: () => [window], intervalMs: 1000 })
    invalidations.flush()
    expect(window.send).not.toHaveBeenCalled()
    invalidations.notify(); invalidations.notify()
    invalidations.flush()
    expect(window.send).toHaveBeenCalledTimes(1)
    expect(vi.getTimerCount()).toBe(0)
  })

  it('dispose() cancels a held notice and ignores everything after it', () => {
    const window = fakeWindow()
    const invalidations = createThreadInvalidations({ windows: () => [window], intervalMs: 200 })
    invalidations.observe('agent:status', { id: 'a' })
    invalidations.dispose()
    expect(vi.getTimerCount()).toBe(0)
    invalidations.observe('agent:status', { id: 'a' }); invalidations.notify(); invalidations.flush()
    vi.advanceTimersByTime(5000)
    expect(window.send).not.toHaveBeenCalled()
    expect(vi.getTimerCount()).toBe(0)
  })
})

/**
 * Push invalidations for the Threads list (replaces the renderer's five-second poll).
 *
 * Main already announces everything that can change a thread row - a conversation's events, its
 * phase, the project list, remote machines, archives, new workspaces - on channels the windows
 * hear. This turns those into one payload-free `threads:changed` notice per burst to every live
 * window. A window answers it by asking `threads:list`, which keeps its trusted-sender check and
 * its async read of the phone state; the notice itself carries nothing a window could not ask for.
 *
 * `phone:changed` is deliberately absent: it is the desktop settings and status of phone access,
 * not a conversation event.
 */
import { THREADS_CHANGED_CHANNEL } from '../shared/threads'

/** The channels that change what the Threads list shows, as main broadcasts them. */
export const THREAD_INVALIDATING_CHANNELS: ReadonlySet<string> = new Set([
  'structured:events', // messages, titles (rename) and archive flags are session events
  'agent:status', // a phase change: working, needs the owner, idle, exited
  'projects:changed', // a project added, renamed, removed, or the General project turned into one
  'remote:changed', // a paired machine's projects and their threads come and go
  'session-archive:changed', // a closed workspace archived or restored
  'sessions:restored' // a workspace reopened or created by a task dispatch
])

/** What `BrowserWindow` already offers; narrowed so the module needs no Electron to be tested. */
export interface ThreadInvalidationWindow {
  isDestroyed(): boolean
  webContents: { isDestroyed(): boolean; send(channel: string): void }
}

export interface ThreadInvalidationDeps {
  /** Every window, live or not; destroyed ones are skipped at send time. */
  windows(): readonly ThreadInvalidationWindow[]
  /**
   * The shortest gap between two notices to a window. An invalidation inside the gap is held and
   * leaves as one trailing notice when it ends, so a streamed answer costs at most one notice per
   * window per gap rather than one per event batch. 200 ms is a choice, not a measurement.
   */
  intervalMs?: number
}

export interface ThreadInvalidations {
  /**
   * Feed it every broadcast `(channel, payload)`. Returns whether the channel can change the list.
   * Never throws, so it is safe inside a broadcast listener.
   */
  observe(channel: string, payload?: unknown): boolean
  /** Invalidate without a channel: for structural handlers that broadcast nothing themselves. */
  notify(): void
  /** Send a held notice now. */
  flush(): void
  dispose(): void
}

export const THREAD_INVALIDATION_INTERVAL_MS = 200

export function createThreadInvalidations(deps: ThreadInvalidationDeps): ThreadInvalidations {
  const intervalMs = Math.max(0, deps.intervalMs ?? THREAD_INVALIDATION_INTERVAL_MS)
  let timer: ReturnType<typeof setTimeout> | null = null
  let disposed = false

  const send = (): void => {
    let windows: readonly ThreadInvalidationWindow[] = []
    try { windows = deps.windows() } catch (error) { console.warn('Thread invalidation could not list windows', error) }
    for (const window of windows) {
      try {
        if (window.isDestroyed() || window.webContents.isDestroyed()) continue
        window.webContents.send(THREADS_CHANGED_CHANNEL)
      } catch (error) { console.warn('Thread invalidation could not reach a window', error) }
    }
  }
  const notify = (): void => {
    if (disposed || timer) return
    timer = setTimeout(() => { timer = null; if (!disposed) send() }, intervalMs)
  }
  return {
    observe(channel, payload) {
      if (!THREAD_INVALIDATING_CHANNELS.has(channel)) return false
      // An empty event batch changes nothing a row shows.
      if (channel === 'structured:events' && Array.isArray(payload) && payload.length === 0) return false
      notify()
      return true
    },
    notify,
    flush() {
      if (disposed || !timer) return
      clearTimeout(timer)
      timer = null
      send()
    },
    dispose() {
      disposed = true
      if (timer) clearTimeout(timer)
      timer = null
    }
  }
}

import { beforeEach, describe, expect, it, vi } from 'vitest'
import { THREADS_CHANGED_CHANNEL } from '../shared/threads'
import { createThreadInvalidations } from '../main/thread-invalidations'

const listeners = new Map<string, Set<(event: unknown, ...args: unknown[]) => void>>()
const ipcRenderer = vi.hoisted(() => ({
  invoke: vi.fn(),
  on: vi.fn(),
  removeListener: vi.fn()
}))
vi.mock('electron', () => ({ ipcRenderer }))

import { threadsBridge } from './threads'

const emit = (channel: string, ...args: unknown[]): void => { for (const listener of [...(listeners.get(channel) ?? [])]) listener({ sender: 'main' }, ...args) }

describe('rank9 threads preload bridge', () => {
  beforeEach(() => {
    listeners.clear()
    ipcRenderer.invoke.mockReset(); ipcRenderer.on.mockReset(); ipcRenderer.removeListener.mockReset()
    ipcRenderer.on.mockImplementation((channel: string, listener: (event: unknown, ...args: unknown[]) => void) => {
      if (!listeners.has(channel)) listeners.set(channel, new Set())
      listeners.get(channel)!.add(listener)
    })
    ipcRenderer.removeListener.mockImplementation((channel: string, listener: (event: unknown, ...args: unknown[]) => void) => { listeners.get(channel)?.delete(listener) })
  })

  it('keeps the invoke calls unchanged', async () => {
    ipcRenderer.invoke.mockResolvedValue('ok')
    await threadsBridge.list('q')
    expect(ipcRenderer.invoke).toHaveBeenCalledWith('threads:list', 'q')
  })

  it('onChanged hears the channel main sends on, hands the listener no payload, and unsubscribes', () => {
    vi.useFakeTimers()
    try {
      const listener = vi.fn()
      const off = threadsBridge.onChanged(listener)
      expect(ipcRenderer.on).toHaveBeenCalledTimes(1)
      // The window main would send to: delivery goes through the same ipcRenderer the bridge listens on.
      const window = { isDestroyed: () => false, webContents: { isDestroyed: () => false, send: (channel: string) => emit(channel) } }
      const invalidations = createThreadInvalidations({ windows: () => [window], intervalMs: 5 })
      invalidations.observe('agent:status', { id: 'x' }); vi.advanceTimersByTime(5)
      expect(listener).toHaveBeenCalledTimes(1)
      expect(listener.mock.calls[0]).toEqual([])
      emit(THREADS_CHANGED_CHANNEL, 'ignored payload')
      expect(listener.mock.calls[1]).toEqual([])
      off()
      expect(ipcRenderer.removeListener).toHaveBeenCalledTimes(1)
      expect(ipcRenderer.removeListener.mock.calls[0]?.[0]).toBe(ipcRenderer.on.mock.calls[0]?.[0])
      invalidations.observe('agent:status', { id: 'x' }); vi.advanceTimersByTime(5)
      expect(listener).toHaveBeenCalledTimes(2)
    } finally { vi.useRealTimers() }
  })

  it('a listener that throws neither breaks the bridge nor the other listeners', () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => undefined)
    const bad = vi.fn(() => { throw new Error('render failed') }), good = vi.fn()
    threadsBridge.onChanged(bad); threadsBridge.onChanged(good)
    expect(() => emit(THREADS_CHANGED_CHANNEL)).not.toThrow()
    expect(good).toHaveBeenCalledTimes(1)
    expect(warn).toHaveBeenCalled()
    warn.mockRestore()
  })
})

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import type { ThreadView } from '../../../shared/threads'
import { createThreadInvalidations, type ThreadInvalidationWindow } from '../../../main/thread-invalidations'
import { createThreadListRefresh, type ThreadListRefresh, type ThreadListRefreshEnvironment, type ThreadListRefreshOptions } from './thread-list-refresh'

const view = (label: string): ThreadView => ({ generalProjectId: null, groups: [], total: 0, hidden: 0, observedAt: label })

interface Deferred { query: string; resolve(label?: string): void; reject(error: unknown): void }

/** A window-less harness: a controllable environment, push bus and a reader whose answers the test settles. */
function harness(overrides: Partial<ThreadListRefreshOptions> = {}) {
  const log: string[] = []
  const pushes = new Set<() => void>()
  const focus = new Set<() => void>()
  const visibility = new Set<() => void>()
  let visible = true
  const environment: ThreadListRefreshEnvironment = {
    isVisible: () => visible,
    onFocus: listener => { focus.add(listener); return () => { focus.delete(listener) } },
    onVisibilityChange: listener => { visibility.add(listener); return () => { visibility.delete(listener) } }
  }
  const reads: Deferred[] = []
  let inFlight = 0, maxInFlight = 0
  const applied: string[] = []
  const options: ThreadListRefreshOptions = {
    environment,
    subscribe: listener => { log.push('subscribe'); pushes.add(listener); return () => { log.push('unsubscribe'); pushes.delete(listener) } },
    read: query => {
      log.push(`read:${query}`)
      inFlight += 1; maxInFlight = Math.max(maxInFlight, inFlight)
      return new Promise<ThreadView>((resolve, reject) => {
        reads.push({
          query,
          resolve: label => { inFlight -= 1; resolve(view(label ?? query)) },
          reject: error => { inFlight -= 1; reject(error) }
        })
      })
    },
    onView: next => { applied.push(next.observedAt) },
    ...overrides
  }
  return {
    log, reads, applied, options, pushes,
    read: (index: number): Deferred => { const read = reads[index]; if (!read) throw new Error(`no read #${index}`); return read },
    get maxInFlight() { return maxInFlight },
    push: () => { for (const listener of [...pushes]) listener() },
    focus: () => { for (const listener of [...focus]) listener() },
    setVisible: (next: boolean) => { visible = next; for (const listener of [...visibility]) listener() },
    listenerCounts: () => ({ pushes: pushes.size, focus: focus.size, visibility: visibility.size })
  }
}

/** Let promise reactions run without moving the fake clock. */
const settled = async (): Promise<void> => { await vi.advanceTimersByTimeAsync(0) }

describe('rank9 thread list refresh lifecycle (renderer)', () => {
  let controller: ThreadListRefresh | undefined
  const unhandled: unknown[] = []
  const onUnhandled = (reason: unknown): void => { unhandled.push(reason) }
  beforeEach(() => { vi.useFakeTimers(); unhandled.length = 0; process.on('unhandledRejection', onUnhandled) })
  afterEach(async () => {
    controller?.dispose(); controller = undefined
    await vi.advanceTimersByTimeAsync(60_000)
    process.off('unhandledRejection', onUnhandled)
    expect(unhandled).toEqual([])
    vi.useRealTimers()
  })

  it('subscribes to pushes before the first read and applies that read', async () => {
    const h = harness()
    controller = createThreadListRefresh(h.options)
    expect(h.log).toEqual(['subscribe', 'read:'])
    h.read(0).resolve('first'); await settled()
    expect(h.applied).toEqual(['first'])
  })

  it('a change that lands between the subscription and the first answer produces a trailing read of newer state', async () => {
    const h = harness()
    controller = createThreadListRefresh(h.options)
    h.push()
    h.read(0).resolve('stale'); await settled()
    expect(h.applied).toEqual(['stale'])
    await vi.advanceTimersByTimeAsync(400)
    expect(h.reads).toHaveLength(2)
    h.read(1).resolve('fresh'); await settled()
    expect(h.applied).toEqual(['stale', 'fresh'])
  })

  it('coalesces a burst of pushes into one read, and spaces consecutive bursts by the minimum interval', async () => {
    const h = harness({ coalesceMs: 60, minIntervalMs: 400 })
    controller = createThreadListRefresh(h.options)
    h.read(0).resolve('initial'); await settled()
    await vi.advanceTimersByTimeAsync(1000)
    for (let index = 0; index < 200; index += 1) { h.push(); controller.invalidate() }
    expect(h.reads).toHaveLength(1)
    await vi.advanceTimersByTimeAsync(59)
    expect(h.reads).toHaveLength(1)
    await vi.advanceTimersByTimeAsync(1)
    expect(h.reads).toHaveLength(2)
    h.read(1).resolve('second'); await settled()
    // Another burst right after the read started: held until minIntervalMs after that start.
    for (let index = 0; index < 50; index += 1) h.push()
    await vi.advanceTimersByTimeAsync(300)
    expect(h.reads).toHaveLength(2)
    await vi.advanceTimersByTimeAsync(100)
    expect(h.reads).toHaveLength(3)
    h.read(2).resolve('third'); await settled()
    await vi.advanceTimersByTimeAsync(10_000)
    expect(h.reads).toHaveLength(3)
    expect(h.maxInFlight).toBe(1)
    expect(h.applied).toEqual(['initial', 'second', 'third'])
  })

  it('an invalidation during a request waits for it, then exactly one trailing read follows; reads never overlap', async () => {
    const h = harness()
    controller = createThreadListRefresh(h.options)
    for (let index = 0; index < 30; index += 1) { h.push(); controller.refreshNow(); await vi.advanceTimersByTimeAsync(20) }
    expect(h.reads).toHaveLength(1)
    h.read(0).resolve('during'); await settled()
    expect(h.applied).toEqual(['during'])
    await vi.advanceTimersByTimeAsync(5000)
    expect(h.reads).toHaveLength(2)
    h.read(1).resolve('trailing'); await settled()
    await vi.advanceTimersByTimeAsync(5000)
    expect(h.reads).toHaveLength(2)
    expect(h.maxInFlight).toBe(1)
    expect(h.applied).toEqual(['during', 'trailing'])
  })

  it('an async reader that resolves the current state when it finishes shows the latest of a rapid sequence', async () => {
    let state = 'v0'
    const h = harness({
      read: async () => { await Promise.resolve(); const seen = state; await new Promise(resolve => setTimeout(resolve, 100)); return view(`${seen}->${state}`) }
    })
    controller = createThreadListRefresh(h.options)
    state = 'v1'; controller.invalidate()
    await vi.advanceTimersByTimeAsync(50)
    state = 'v2'; controller.invalidate()
    await vi.advanceTimersByTimeAsync(5000)
    expect(h.applied.at(-1)).toBe('v2->v2')
  })

  it('drops an out-of-order answer for an old query and never overlaps the next query read', async () => {
    const h = harness()
    controller = createThreadListRefresh(h.options)
    h.read(0).resolve(); await settled()
    await vi.advanceTimersByTimeAsync(1000)
    controller.setQuery('a')
    expect(h.log.at(-1)).toBe('read:a')
    controller.setQuery('ab'); controller.setQuery('abc')
    expect(h.reads.map(read => read.query)).toEqual(['', 'a'])
    h.read(1).resolve('result-a'); await settled()
    expect(h.applied).toEqual(['']) // 'a' is no longer the query, so its answer is not shown
    expect(h.reads.map(read => read.query)).toEqual(['', 'a', 'abc']) // 'ab' was superseded unread
    h.read(2).resolve('result-abc'); await settled()
    expect(h.applied).toEqual(['', 'result-abc'])
    expect(h.maxInFlight).toBe(1)
  })

  it('does not show an old query result that arrives after a newer one was already shown', async () => {
    const h = harness({ readTimeoutMs: 1000 })
    controller = createThreadListRefresh(h.options)
    h.read(0).resolve(); await settled()
    controller.setQuery('slow')
    controller.setQuery('fast')
    await vi.advanceTimersByTimeAsync(1000) // 'slow' never answers in time and is abandoned
    expect(h.reads.map(read => read.query)).toContain('fast')
    h.reads.find(read => read.query === 'fast')!.resolve('fast-result'); await settled()
    h.reads.find(read => read.query === 'slow')!.resolve('slow-late'); await settled()
    expect(h.applied).toEqual(['', 'fast-result'])
  })

  it('collapsing or hiding suppresses reads and drops the answer that was in flight; showing again catches up', async () => {
    const h = harness()
    controller = createThreadListRefresh(h.options)
    controller.setCollapsed(true)
    h.read(0).resolve('arrives-after-collapse'); await settled()
    expect(h.applied).toEqual([])
    for (let index = 0; index < 20; index += 1) h.push()
    controller.invalidate(); controller.refreshNow(); controller.setQuery('typed while collapsed'); h.focus()
    await vi.advanceTimersByTimeAsync(60_000)
    expect(h.reads).toHaveLength(1)
    controller.setCollapsed(false)
    expect(h.log.at(-1)).toBe('read:typed while collapsed')
    h.read(1).resolve('after-expand'); await settled()
    expect(h.applied).toEqual(['after-expand'])

    h.setVisible(false)
    for (let index = 0; index < 20; index += 1) h.push()
    h.focus()
    await vi.advanceTimersByTimeAsync(60_000)
    expect(h.reads).toHaveLength(2)
    h.setVisible(true)
    expect(h.reads).toHaveLength(3)
    h.read(2).resolve('after-show'); await settled()
    expect(h.applied).toEqual(['after-expand', 'after-show'])
  })

  it('a window focus reads once while shown and not at all while hidden or collapsed', async () => {
    const h = harness()
    controller = createThreadListRefresh(h.options)
    h.read(0).resolve(); await settled()
    await vi.advanceTimersByTimeAsync(1000)
    h.focus()
    expect(h.reads).toHaveLength(2)
    h.read(1).resolve(); await settled()
    controller.setCollapsed(true)
    h.focus()
    expect(h.reads).toHaveLength(2)
  })

  it('does not read at all when it starts collapsed or hidden, and reads once when first shown', async () => {
    const hidden = harness()
    hidden.setVisible(false)
    controller = createThreadListRefresh({ ...hidden.options, collapsed: false, environment: { ...hidden.options.environment } })
    expect(hidden.reads).toHaveLength(0)
    hidden.setVisible(true)
    expect(hidden.reads).toHaveLength(1)
    controller.dispose()
    const collapsed = harness()
    controller = createThreadListRefresh({ ...collapsed.options, collapsed: true })
    expect(collapsed.log).toEqual(['subscribe'])
    controller.setCollapsed(false)
    expect(collapsed.reads).toHaveLength(1)
  })

  it('retries a rejected read with backoff, reports it, and recovers without unhandled rejections', async () => {
    const onError = vi.fn()
    const h = harness({ onError, retryMs: 1000, maxRetryMs: 3000 })
    controller = createThreadListRefresh(h.options)
    h.read(0).reject(new Error('ipc closed')); await settled()
    expect(h.applied).toEqual([])
    await vi.advanceTimersByTimeAsync(999)
    expect(h.reads).toHaveLength(1)
    await vi.advanceTimersByTimeAsync(1)
    expect(h.reads).toHaveLength(2)
    h.read(1).reject(new Error('still closed')); await settled()
    await vi.advanceTimersByTimeAsync(1999)
    expect(h.reads).toHaveLength(2)
    await vi.advanceTimersByTimeAsync(1)
    expect(h.reads).toHaveLength(3)
    h.read(2).reject(new Error('third')); await settled()
    await vi.advanceTimersByTimeAsync(3000) // capped, not 4000
    expect(h.reads).toHaveLength(4)
    h.read(3).resolve('recovered'); await settled()
    expect(h.applied).toEqual(['recovered'])
    expect(onError).toHaveBeenCalledTimes(3)
    await vi.advanceTimersByTimeAsync(60_000)
    expect(h.reads).toHaveLength(4)
  })

  it('stops retrying once the list is hidden and reads again when it is shown', async () => {
    const h = harness({ retryMs: 1000 })
    controller = createThreadListRefresh(h.options)
    h.read(0).reject(new Error('down')); await settled()
    controller.setCollapsed(true)
    await vi.advanceTimersByTimeAsync(60_000)
    expect(h.reads).toHaveLength(1)
    controller.setCollapsed(false)
    expect(h.reads).toHaveLength(2)
  })

  it('treats a reader that throws synchronously, or returns a plain value, as a read', async () => {
    let mode: 'throw' | 'value' = 'throw'
    const onError = vi.fn()
    const h = harness({ onError, retryMs: 500, read: () => { if (mode === 'throw') throw new Error('bridge missing'); return view('plain') } })
    controller = createThreadListRefresh(h.options)
    expect(onError).toHaveBeenCalledTimes(0) // reported on the promise turn, not thrown at the caller
    await settled()
    expect(onError).toHaveBeenCalledTimes(1)
    mode = 'value'
